using Alterverse.Characters;using Alterverse.Combat;using UnityEngine;
namespace Alterverse.Visuals
{
public sealed class StylizedHeroVisual:MonoBehaviour
{
private HeroIdentity identity;private TeamMember team;private bool built;private Color accent,dark,teamEdge;private Transform root;private void Start(){Build();}public void Build(){if(built)return;identity=GetComponent<HeroIdentity>();team=GetComponent<TeamMember>();if(identity==null)return;built=true;accent=StylizedArtDirection.HeroAccent(identity.Hero);dark=Color.Lerp(accent,StylizedArtDirection.Ink,.66f);teamEdge=team!=null&&team.Team==1?StylizedArtDirection.LumenEnergy:StylizedArtDirection.ZeroEnergy;Renderer baseRenderer=GetComponent<Renderer>();if(baseRenderer!=null)baseRenderer.enabled=false;root=new GameObject("DF_VisualRoot").transform;root.SetParent(transform,false);switch(identity.Hero){case HeroId.Kaelon:BuildKaelon();break;case HeroId.Nyra:BuildNyra();break;case HeroId.Elyra:BuildElyra();break;case HeroId.Mira:BuildMira();break;case HeroId.Rook:BuildRook();break;default:BuildVeyr();break;}CreateLegs(identity.Hero==HeroId.Kaelon||identity.Hero==HeroId.Rook?.24f:.17f);Create("TeamMark",PrimitiveType.Cylinder,new Vector3(0,-.96f,0),new Vector3(.76f,.018f,.76f),teamEdge,Vector3.zero,transform);if(GetComponent<HeroVisualMotion>()==null)gameObject.AddComponent<HeroVisualMotion>();}
private void CreateLegs(float width){Create("LegL",PrimitiveType.Capsule,new Vector3(-width,-.62f,0),new Vector3(.18f,.45f,.18f),dark);Create("LegR",PrimitiveType.Capsule,new Vector3(width,-.62f,0),new Vector3(.18f,.45f,.18f),dark);Create("BootL",PrimitiveType.Cube,new Vector3(-width,-.91f,.08f),new Vector3(.24f,.14f,.36f),accent);Create("BootR",PrimitiveType.Cube,new Vector3(width,-.91f,.08f),new Vector3(.24f,.14f,.36f),accent);}
private void BuildVeyr(){Create("Torso",PrimitiveType.Capsule,new Vector3(0,.02f,0),new Vector3(.48f,.72f,.4f),dark);Create("Head",PrimitiveType.Sphere,new Vector3(0,.83f,0),new Vector3(.48f,.5f,.48f),accent);Create("Mask",PrimitiveType.Cube,new Vector3(0,.82f,.23f),new Vector3(.34f,.15f,.08f),teamEdge);Create("ArmL",PrimitiveType.Capsule,new Vector3(-.36f,.12f,.02f),new Vector3(.18f,.48f,.18f),dark,new Vector3(0,0,-14));Create("ArmR",PrimitiveType.Capsule,new Vector3(.36f,.12f,.02f),new Vector3(.18f,.48f,.18f),dark,new Vector3(0,0,14));Create("BladeR",PrimitiveType.Cube,new Vector3(.52f,-.02f,.32f),new Vector3(.08f,.72f,.11f),accent,new Vector3(25,0,-16));Create("BladeL",PrimitiveType.Cube,new Vector3(-.48f,.02f,.22f),new Vector3(.07f,.48f,.09f),teamEdge,new Vector3(18,0,20));}
private void BuildKaelon(){Create("Torso",PrimitiveType.Cube,new Vector3(0,.05f,0),new Vector3(.82f,.82f,.64f),dark);Create("Chest",PrimitiveType.Cube,new Vector3(0,.24f,.34f),new Vector3(.58f,.35f,.12f),accent);Create("Head",PrimitiveType.Cube,new Vector3(0,.88f,0),new Vector3(.52f,.48f,.5f),dark);Create("Visor",PrimitiveType.Cube,new Vector3(0,.91f,.27f),new Vector3(.4f,.11f,.06f),teamEdge);Create("ShoulderL",PrimitiveType.Cube,new Vector3(-.62f,.43f,0),new Vector3(.5f,.36f,.72f),accent);Create("ShoulderR",PrimitiveType.Cube,new Vector3(.62f,.43f,0),new Vector3(.5f,.36f,.72f),accent);Create("Shield",PrimitiveType.Cube,new Vector3(-.78f,-.02f,.28f),new Vector3(.14f,.92f,.78f),teamEdge,new Vector3(0,0,-6));}
private void BuildNyra(){Create("Torso",PrimitiveType.Capsule,new Vector3(0,.04f,0),new Vector3(.42f,.68f,.38f),dark);Create("Head",PrimitiveType.Sphere,new Vector3(0,.82f,0),new Vector3(.45f,.48f,.45f),accent);Create("Visor",PrimitiveType.Cube,new Vector3(0,.84f,.23f),new Vector3(.34f,.1f,.06f),teamEdge);Create("Rifle",PrimitiveType.Cube,new Vector3(.43f,.12f,.55f),new Vector3(.13f,.15f,1.42f),accent,new Vector3(0,4,-7));Create("Barrel",PrimitiveType.Cube,new Vector3(.43f,.12f,1.28f),new Vector3(.08f,.08f,.36f),teamEdge);Create("Cape",PrimitiveType.Cube,new Vector3(-.18f,.05f,-.27f),new Vector3(.58f,.68f,.06f),dark,new Vector3(8,0,8));}
private void BuildElyra(){Create("Torso",PrimitiveType.Capsule,new Vector3(0,.05f,0),new Vector3(.44f,.7f,.4f),dark);Create("Head",PrimitiveType.Sphere,new Vector3(0,.84f,0),new Vector3(.46f,.5f,.46f),accent);Create("CrownL",PrimitiveType.Cube,new Vector3(-.2f,1.16f,0),new Vector3(.09f,.38f,.09f),accent,new Vector3(0,0,-20));Create("CrownR",PrimitiveType.Cube,new Vector3(.2f,1.16f,0),new Vector3(.09f,.38f,.09f),teamEdge,new Vector3(0,0,20));Create("OrbitL",PrimitiveType.Sphere,new Vector3(.72f,.5f,.04f),Vector3.one*.24f,accent);Create("OrbitR",PrimitiveType.Sphere,new Vector3(-.68f,.18f,.18f),Vector3.one*.18f,teamEdge);Create("Mantle",PrimitiveType.Cube,new Vector3(0,.4f,-.25f),new Vector3(1.02f,.12f,.42f),accent);}
private void BuildMira(){Create("Torso",PrimitiveType.Capsule,new Vector3(0,.03f,0),new Vector3(.45f,.7f,.4f),dark);Create("Head",PrimitiveType.Sphere,new Vector3(0,.84f,0),new Vector3(.47f,.5f,.47f),accent);Create("Crown",PrimitiveType.Sphere,new Vector3(0,1.16f,0),Vector3.one*.19f,teamEdge);Create("WingL",PrimitiveType.Cube,new Vector3(-.5f,.35f,-.26f),new Vector3(.78f,.1f,.42f),accent,new Vector3(0,-18,-18));Create("WingR",PrimitiveType.Cube,new Vector3(.5f,.35f,-.26f),new Vector3(.78f,.1f,.42f),accent,new Vector3(0,18,18));Create("Staff",PrimitiveType.Cylinder,new Vector3(.58f,.08f,.18f),new Vector3(.07f,.65f,.07f),dark,new Vector3(0,0,-8));Create("Bloom",PrimitiveType.Sphere,new Vector3(.68f,.73f,.18f),Vector3.one*.22f,accent);}
private void BuildRook(){Create("Torso",PrimitiveType.Cube,new Vector3(0,.02f,0),new Vector3(.78f,.76f,.64f),dark);Create("Head",PrimitiveType.Sphere,new Vector3(0,.82f,0),new Vector3(.55f,.48f,.55f),accent);Create("Jaw",PrimitiveType.Cube,new Vector3(0,.7f,.28f),new Vector3(.42f,.18f,.14f),dark);Create("GauntletL",PrimitiveType.Cube,new Vector3(-.64f,-.02f,.22f),new Vector3(.5f,.56f,.66f),dark,new Vector3(0,0,-8));Create("GauntletR",PrimitiveType.Cube,new Vector3(.68f,-.02f,.26f),new Vector3(.66f,.66f,.78f),accent,new Vector3(0,0,8));Create("BackPlate",PrimitiveType.Cube,new Vector3(0,.24f,-.36f),new Vector3(.9f,.58f,.14f),teamEdge);}
private GameObject Create(string n,PrimitiveType type,Vector3 pos,Vector3 scale,Color color,Vector3 rotation=default,Transform parent=null){GameObject p=GameObject.CreatePrimitive(type);p.name="DF_"+n;p.transform.SetParent(parent!=null?parent:root,false);p.transform.localPosition=pos;p.transform.localScale=scale;p.transform.localRotation=Quaternion.Euler(rotation);Collider c=p.GetComponent<Collider>();if(c!=null)c.enabled=false;Renderer r=p.GetComponent<Renderer>();if(r!=null)r.material.color=color;return p;}
}
}
